'use strict';
let online=false, productFocus=null, videoFocus=null;
const selectedProducts=new Set(),selectedAssets=new Set(),selectedVideos=new Set(),selectedMusic=new Set();
const musicModes=[['local','本地自动匹配'],['none','无音乐'],['ai','AI自动选曲（等待接入）'],['single','指定单曲'],['multi','多曲选择']];
const languageNames={th:'泰文',en:'英文',zh:'中文（预留）'};
const sourceNames={local:'本地导入',tiktok:'店铺下载',generated:'生成记录',sku_pattern:'商品规格图名',sku_material:'商品规格材质',sku_color:'商品规格颜色',product_title:'商品标题',product_details:'商品详情',existing:'已有关键词资料',video_titles:'已有视频标题'};
const associationNames={none:'不关联商品',source:'使用来源商品',selected:'指定商品'};
const matchNames={matched:'已匹配',unmatched:'没有匹配项',not_requested:'未启用'};
const transitionSummary=ids=>(ids||['none']).map(id=>(data.transitions||[]).find(t=>t.id===id)?.name||({none:'直接切换',fade:'淡入淡出',slideleft:'左滑',slideright:'右滑',slideup:'上滑',slidedown:'下滑'}[id])||'历史转场').join(' → ');
const taskTransitions=cfg=>cfg.transitions||[cfg.transition||'none'];
const resolutionLabel=cfg=>(data.resolution_options||[]).find(r=>r.id===(cfg.resolution||'1080x1920'))?.name||String(cfg.resolution||'1080x1920').replace('x',' × ');
const sourceLabel=value=>sourceNames[value]||value||'未提供';
const taskLabel=t=>data.batches.find(b=>b.id===t?.batch_id)?.name||'视频生产任务';
const motionNames={none:'静止完整展示',zoom:'安全轻微缩放',pan:'安全轻微平移'};
let productStatus='all',storeFilter='',assetKind='all',assetSource='',assetRelation='';
const oldActions=actions,oldRender=render,oldHome=home;
async function api(name,payload){const response=await fetch('/api/'+name,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const r=await response.json();if(!response.ok){const message=r.error||'本地服务连接失败';const fields=[[/转场时长|转场时间/,'batch-transition-time'],[/音乐淡入淡出/,'batch-fade'],[/音乐音量/,'batch-volume'],[/视频尺寸|分辨率/,'batch-resolution'],[/总时长/,'batch-total'],[/逐图|展示时间/,'batch-seconds'],[/音乐/,'batch-music'],[/输出目录/,'batch-output'],[/生成视频数量/,'batch-count-number'],[/没有可用图片|素材文件缺失|请选择至少一个商品/,'batch-objects'],[/请选择发布关联商品/,'copy-products']];throw fieldError(message,fields.find(([pattern,id])=>pattern.test(message)&&document.getElementById(id))?.[1])}return r}
async function loadState(redraw=true){const snapshot=await api('state');Object.assign(data,snapshot);settings={...settings,...snapshot.settings};online=true;if(redraw)render()}
const getProduct=id=>data.products.find(p=>p.id===id);
const getTask=id=>data.tasks.find(p=>p.id===id);
const getAsset=id=>data.assets.find(p=>p.id===id);
const getVideo=id=>data.videos.find(p=>p.id===id);
const getSku=id=>data.skus?.find(p=>p.id===id)?.name||'—';
const productAssets=id=>(data.links||[]).filter(l=>l.product_id===id).sort((a,b)=>a.position-b.position).map(l=>getAsset(l.asset_id)).filter(Boolean);
const media=(a)=>'/media/asset/'+encodeURIComponent(a.id);
const videoURL=v=>'/media/video/'+encodeURIComponent(v.id);
const statusNames={waiting:'等待中',running:'生产中',done:'已完成',failed:'失败',pending:'待发布',uploading:'上传中',uploaded:'已上传',published:'发布成功'};
const statusBadge=s=>`<span class="status ${esc(s)}">${statusNames[s]||'未记录状态'}</span>`;
const rowtable=(headers,rows,emptyText='暂无记录')=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="table-empty">${emptyText}</td></tr>`}</tbody></table></div>`;
const check=(kind,id)=>`<input type="checkbox" data-select="${kind}" value="${esc(id)}" aria-label="选择 ${esc(kind==='product'?getProduct(id)?.title:kind==='asset'?getAsset(id)?.name:JSON.parse(getVideo(id)?.content||'{}').title||'视频')}" ${(kind==='product'?selectedProducts:kind==='asset'?selectedAssets:selectedVideos).has(id)?'checked':''}>`;
const searchable=(...fields)=>!query||fields.some(v=>String(v||'').toLowerCase().includes(query.toLowerCase()));
const thumbnail=a=>a?.kind==='image'&&a.available!==false?`<img class="thumb" src="${media(a)}" alt="${esc(a.name)}">`:icon(a?.kind==='music'?'music':'video');
const bytes=n=>n>1024**3?(n/1024**3).toFixed(1)+' GB':n>1024**2?(n/1024**2).toFixed(1)+' MB':(n/1024).toFixed(1)+' KB';
const pstatus=id=>{const ts=data.tasks.filter(t=>t.product_id===id);return ts.some(t=>t.status==='running')?'running':ts.some(t=>t.status==='waiting')?'waiting':ts.some(t=>t.status==='failed')?'failed':ts.length?'done':'unproduced'};
function updateStorage(){if(!data.storage)return;document.getElementById('storage-caption').textContent=bytes(data.storage.total-data.storage.free)+' / '+bytes(data.storage.total)}
render=function(){oldRender();updateStorage()};
save=async function(){try{if(settings.production)for(const k of ['music','music_ids','music_order','output_dir'])if(settings[k]!==undefined)settings.production[k]=settings[k];await api('settings',settings);toast('默认配置已保存');await loadState(false)}catch(e){reportError(e)}};
config=function(){const d=settings.production||{};return panel('当前生产配置',`<div class="field"><label class="label">素材来源</label>${select('source',[['local','本地素材'],['products','商品库'],['tiktok','TikTok 店铺商品']],settings.source)}</div><p class="note">已选择 ${settings.source==='local'?selectedAssets.size+' 份素材':selectedProducts.size+' 个商品'}</p>${go('选择商品 / 素材',settings.source==='local'?'assets':'products')}<dl class="detail-list"><dt>转场效果</dt><dd>${esc(transitionSummary(d.transitions))}</dd><dt>视频尺寸</dt><dd>${esc(resolutionLabel(d))}</dd><dt>图片适配</dt><dd>完整显示，等比例留白</dd><dt>文案语言</dt><dd>${languageNames[d.local_copy?.language||'th']}</dd><dt>音乐方式</dt><dd>${esc(musicModes.find(([id])=>id===(d.music||settings.music))?.[1]||'无音乐')}</dd><dt>输出目录</dt><dd>${esc(d.output_dir||settings.output_dir||data.storage?.output||'')}</dd></dl><p class="note">默认每张图片展示 ${d.image_duration||2} 秒；任务中可调整。方图在竖屏中上下留白，完整保留商品。</p>${btn('查看或编辑生产设置','create-task','',false,'settings')}${btn('创建生产任务','create-task','primary',false,'play')}`,'','config')};
home=function(){let html=oldHome();if(data.products.length){const start=html.indexOf('<div class="empty compact">');const end=html.indexOf('</section>',start);if(start>=0&&end>start){const cards=`<div class="product-cards">${data.products.slice(-6).reverse().map(p=>{const a=productAssets(p.id).find(a=>a.kind==='image');return `<a class="product-card" href="#products" data-product-focus="${esc(p.id)}">${a?`<img src="${media(a)}" alt="${esc(p.title)}">`:`<div class="asset-thumb">${icon('box')}</div>`}<b>${esc(p.title)}</b><small>商品编号：${esc(p.id)}</small></a>`}).join('')}</div>`;html=html.slice(0,start)+cards+html.slice(end)}}const oldTable=table(['任务名称','素材来源','对象数量','转场效果','状态','进度','开始时间','操作'],'尚未创建生产任务');html=html.replace(oldTable,taskRows(data.tasks.slice(-5).reverse()));html=html.replace('生产任务 <span class="note">(0)</span>',`生产任务 <span class="note">(${data.tasks.length})</span>`);return html};
products=function(){const shown=data.products.filter(p=>searchable(p.id,p.title,...(data.skus||[]).filter(s=>s.product_id===p.id).map(s=>s.name))).filter(p=>(!storeFilter||p.store===storeFilter)&&(productStatus==='all'||pstatus(p.id)===productStatus));const p=getProduct(productFocus);const rows=shown.map(p=>`<tr class="${p.id===productFocus?'row-selected':''}"><td>${check('product',p.id)}</td><td>${btn(`<b>${esc(p.id)}</b>`,'focus-product:'+p.id,'row-link')}<span class="row-sub">${esc(p.title)}</span></td><td>${esc(p.store)||'—'}</td><td>${data.skus.filter(s=>s.product_id===p.id).length}</td><td>${productAssets(p.id).length}</td><td>${data.tasks.filter(t=>t.product_id===p.id&&t.status==='done').length}</td><td>${pstatus(p.id)==='unproduced'?'<span class="note">未生产</span>':statusBadge(pstatus(p.id))}</td><td>${btn('管理','focus-product:'+p.id,'link')}</td></tr>`).join('');return heading('商品库','统一管理商品、商品规格、关联素材与生成视频',btn('导入商品','import-products','',false,'download')+btn('新建商品','new-product','primary',false,'plus'))+`<div class="toolbar">${search('搜索商品编号、标题或 商品规格…')}<div class="filters"><select id="store-filter" aria-label="店铺筛选"><option value="">全部店铺</option>${data.stores.map(s=>`<option ${storeFilter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="production-filter" aria-label="生产状态筛选">${[['all','全部生产状态'],['unproduced','未生产'],['waiting','等待中'],['running','生产中'],['done','已生成'],['failed','失败']].map(([s,n])=>`<option value="${s}" ${productStatus===s?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="split">${panel(`全部商品 <span class="note">(${data.products.length})</span>`,rowtable(['选择','商品编号 / 标题','店铺','商品规格','素材','视频','生产状态','操作'],rows,noRecords())+(!data.products.length?empty('添加你的第一个商品','商品可关联多个 商品规格、多份素材和多条视频。','box',btn('新建商品','new-product','primary',false,'plus'),'compact'):'')+`<div class="footer-actions"><span>已选择 ${selectedProducts.size} 个商品</span>${btn('创建生产任务','product-tasks','',!selectedProducts.size,'play')}</div>`)}${panel('商品关联信息',p?`<h3>${esc(p.title)}</h3><dl class="detail-list"><dt>商品编号</dt><dd>${esc(p.id)}</dd><dt>店铺</dt><dd>${esc(p.store)||'—'}</dd><dt>商品链接</dt><dd>${esc(p.url)||'—'}</dd><dt>商品规格</dt><dd>${data.skus.filter(s=>s.product_id===p.id).map(s=>esc(s.name)).join('<br>')||'—'}</dd></dl><div class="divider"></div><h3>关联素材 (${productAssets(p.id).length})</h3><div class="detail-assets">${productAssets(p.id).map(a=>thumbnail(a)).join('')}</div><div class="actions">${btn('关联素材','link-assets:'+p.id,'',false,'link')}${btn('编辑商品','edit-product:'+p.id,'')}</div>`:`<div class="detail-empty">${icon('box')}<span>选择商品，查看关联信息</span></div>`)}</div>`};
assets=function(){let shown=data.assets.filter(a=>!a.deleted&&searchable(a.name)).filter(a=>(tab==='all'||a.kind===tab)&&(!assetSource||a.source===assetSource)&&(!assetRelation||(assetRelation==='linked')===data.links.some(l=>l.asset_id===a.id)));const body=view==='grid'?`<div class="asset-grid">${shown.map(a=>`<article class="asset-card"><div class="asset-thumb">${a.kind==='image'?`<img src="${media(a)}" alt="${esc(a.name)}">`:icon(a.kind==='music'?'music':'video')}</div><div class="asset-meta"><label>${check('asset',a.id)}<span title="${esc(a.name)}">${esc(a.name)}</span></label><small>${bytes(a.size)} · ${a.source==='local'?'本地导入':'店铺下载'}</small>${btn('预览','preview-asset:'+a.id,'link')}</div></article>`).join('')}</div>`:rowtable(['选择','素材名称','类型','来源','关联商品','大小','操作'],shown.map(a=>`<tr><td>${check('asset',a.id)}</td><td>${esc(a.name)}</td><td>${{image:'图片',video:'视频',music:'音乐'}[a.kind]}</td><td>${a.source==='local'?'本地':'店铺'}</td><td>${data.links.filter(l=>l.asset_id===a.id).map(l=>esc(l.product_id)).join(', ')||'未绑定'}</td><td>${bytes(a.size)}</td><td>${btn('预览','preview-asset:'+a.id,'link')}</td></tr>`).join(''),noRecords());return heading('素材中心','图片、视频与音乐统一管理，保留原名，可不绑定商品',btn('导入文件夹','import-folder','',false,'folder')+btn('导入素材','import','primary',false,'plus'))+`<div class="toolbar">${search('搜索素材名称…')}<div class="filters"><select id="asset-source" aria-label="素材来源">${[['','全部来源'],['local','本地导入'],['tiktok','TikTok 下载']].map(([v,n])=>`<option value="${v}" ${assetSource===v?'selected':''}>${n}</option>`).join('')}</select><select id="asset-relation" aria-label="关联状态">${[['','全部关联状态'],['linked','已绑定商品'],['unlinked','未绑定商品']].map(([v,n])=>`<option value="${v}" ${assetRelation===v?'selected':''}>${n}</option>`).join('')}</select><div class="view-toggle">${btn(icon('grid'),'view:grid',view==='grid'?'active':'')}${btn(icon('list'),'view:list',view==='list'?'active':'')}</div></div></div><div class="panel">${tabs([['all','全部素材',data.assets.length],...['image','video','music'].map(k=>[k,{image:'图片',video:'视频',music:'音乐'}[k],data.assets.filter(a=>a.kind===k).length])])}${shown.length?body:empty(query?noRecords():'导入本地生产素材','图片、视频和音乐使用同一素材体系。','folder',btn('导入素材','import','primary',false,'plus'),'wide')}<div class="footer-actions"><span>已选择 ${selectedAssets.size} 份素材</span><div class="actions">${btn('关联商品','assets-link','',!selectedAssets.size,'link')}${btn('创建生产任务','asset-tasks','',!selectedAssets.size,'play')}</div></div></div>`};
function taskRows(tasks){return rowtable(['任务 / 商品','商品规格','素材','转场效果','状态','进度','输出 / 原因','操作'],tasks.map(t=>`<tr><td><b class="row-title">${esc(taskLabel(t))}</b><small class="row-sub">${esc(t.product_id||'独立素材组')}</small></td><td>${esc(getSku(t.sku_id))}</td><td>${JSON.parse(t.assets).length}</td><td>${esc(transitionSummary(taskTransitions(JSON.parse(t.config))))}</td><td>${statusBadge(t.status)}</td><td><progress class="progress" max="100" value="${t.progress}"></progress>${t.progress}%</td><td><span class="row-sub" title="${esc(t.error||t.output||'')}">${esc(t.error||t.output||'—')}</span></td><td>${t.status==='failed'?btn('重试','retry:'+t.id,'link'):t.status==='done'?go('查看视频','videos','link'):''}</td></tr>`).join(''),noRecords())}
taskPage=function(){return heading('生产任务','按所选商品或素材批量生成，保存每条视频的真实参数与来源',btn('创建生产任务','create-task','primary',false,'plus'))+countStats()+`<div class="panel">${tabs([['all','全部任务',data.tasks.length],...['waiting','running','done','failed'].map(s=>[s,statusNames[s],data.tasks.filter(t=>t.status===s).length])])}<div class="toolbar">${search('搜索任务、商品编号…')}</div>${taskRows(data.tasks.filter(t=>(tab==='all'||t.status===tab)&&searchable(t.product_id,t.id,taskLabel(t))).slice().reverse())}</div>`};
const videoTask=v=>getTask(v.task_id);
function publicationRows(){return rowtable(['视频 / 商品','商品规格','发布目标','发布状态','失败原因 / 说明','时间','操作'],data.publications.filter(p=>(route!=='publish'||tab==='all'||p.status===tab)&&searchable(p.id,videoTask(getVideo(p.video_id)||{})?.product_id,p.target)).map(p=>{const v=getVideo(p.video_id),t=v&&videoTask(v);return `<tr><td>${esc(t?.product_id||'独立素材视频')}<small class="row-sub">${esc(v?.path||'')}</small></td><td>${esc(getSku(t?.sku_id))}</td><td>${esc(p.target)||'等待连接环境'}</td><td>${statusBadge(p.status)}</td><td><span class="row-sub">${esc(p.error||'—')}</span></td><td>${esc(p.created)}</td><td>${btn('重新执行','','',true,'refresh')}</td></tr>`}).join(''),'暂无发布任务')}
publicationQueue=function(){return panel('发布任务队列',`<p class="note">等待真实环境连接；视频生成成功不会自动标记为发布成功。</p>${publicationRows()}`,go('发布中心','publish','link','arrow'))};
function vstate(v){const ps=data.publications.filter(p=>p.video_id===v.id);return ps.some(p=>p.status==='published')?'published':ps.some(p=>p.status==='failed')?'failed':'pending'}
videoPage=function(){const shown=data.videos.filter(v=>tab==='trash'?v.trashed:!v.trashed&&(tab==='all'||(tab==='published'?vstate(v)==='published':vstate(v)===tab))).filter(v=>{const t=videoTask(v),p=getProduct(t?.product_id);return searchable(t?.product_id,p?.title,getSku(t?.sku_id))});const v=getVideo(videoFocus),t=v&&videoTask(v),p=t&&getProduct(t.product_id);return flow('videos')+heading('视频管理','管理已生成视频，预览、追溯来源并加入发布任务',btn('导出列表','export-videos','',!data.videos.length,'download'))+`<div class="toolbar">${search('搜索商品编号、标题或 商品规格…')}${btn('批量加入发布','queue-selected','primary',!selectedVideos.size,'send')}</div><div class="split"><div class="panel">${tabs([['all','全部视频',data.videos.filter(v=>!v.trashed).length],['pending','待发布',data.videos.filter(v=>!v.trashed&&vstate(v)==='pending').length],['published','已发布',data.videos.filter(v=>!v.trashed&&vstate(v)==='published').length],['failed','发布失败',data.videos.filter(v=>!v.trashed&&vstate(v)==='failed').length],['trash','回收站',data.videos.filter(v=>v.trashed).length]])}${rowtable(['选择','预览','商品信息','商品规格','时长','生成时间','状态','操作'],shown.map(v=>{const t=videoTask(v),p=getProduct(t.product_id),a=getAsset(JSON.parse(t.assets)[0]);return `<tr class="${videoFocus===v.id?'row-selected':''}"><td>${check('video',v.id)}</td><td>${btn(thumbnail(a),'focus-video:'+v.id,'link')}</td><td><b>${esc(t.product_id||'独立素材组')}</b><small class="row-sub">${esc(p?.title||v.path)}</small></td><td>${esc(getSku(t.sku_id))}</td><td>${v.duration.toFixed(1)} 秒</td><td>${esc(v.created)}</td><td>${!v.available?'<span class="note">文件已清理或缺失</span>':v.trashed?'<span class="note">回收站</span>':statusBadge(vstate(v))}</td><td>${v.trashed?btn('恢复','restore:'+v.id,'link'):btn('查看','focus-video:'+v.id,'link')}</td></tr>`}).join(''),noRecords())}${!data.videos.length?empty('生成的视频将显示在这里','视频保留实际使用的素材、转场效果及任务记录。','video',go('前往生产任务','tasks','','tasks'),'compact'):''}<div class="footer-actions"><span>已选择 ${selectedVideos.size} 个视频</span>${btn('移入回收站','trash-selected','danger',!selectedVideos.size,'trash')}</div></div><div class="panel"><h3>视频预览与关联信息</h3><div class="video-preview">${v?.available?`<video controls preload="metadata" src="${videoURL(v)}"></video>`:icon('play')}</div><dl class="detail-list">${[['商品编号',t?.product_id],['商品标题',p?.title],['商品规格',getSku(t?.sku_id)],['转场效果',t?transitionSummary(taskTransitions(JSON.parse(t.config))):'—'],['视频尺寸',t?resolutionLabel(JSON.parse(t.config)):'—'],['图片适配','完整显示 · 等比例留白'],['生产任务',t?taskLabel(t):'—'],['生成时间',v?.created],['文件路径',v?v.resolved_path||v.path:null],['商品链接',p?.url]].map(([k,val])=>`<dt>${k}</dt><dd>${esc(val||'—')}</dd>`).join('')}</dl><div class="divider"></div><h3>原始素材 (${t?JSON.parse(t.assets).length:0})</h3><div class="detail-assets">${t?JSON.parse(t.assets).map(getAsset).filter(Boolean).map(thumbnail).join(''):''}</div><div class="actions">${btn('打开文件','open-video:'+(v?.id||''),'',!v?.available,'folder')}${btn('重新生成','regenerate:'+(v?.id||''),'',!v,'refresh')}</div></div></div>${v?videoDetails(v):''}${publicationQueue()}`};
publishPage=function(){return heading('发布中心','独立记录上传状态与最终发布结果',`<span class="status waiting">等待连接 TikTok 店铺环境</span>`)+`<div class="info-banner">${icon('clock')}尚未执行真实上传或发布。队列保留到环境接入后继续处理。</div><div class="panel">${tabs([['all','全部任务',data.publications.length],...['pending','uploading','uploaded','published','failed'].map(s=>[s,statusNames[s],data.publications.filter(p=>p.status===s).length])])}<div class="toolbar">${search('搜索商品或发布任务…')}${btn('开始发布','','primary',true,'send')}</div>${publicationRows()}${data.publications.length?'':empty('从视频管理添加发布任务','视频生成与发布状态分别记录。','send',go('选择视频','videos','','video'),'compact')}</div>`};
settingsPage=function(){const d=settings.production||{};return heading('设置','保存默认生产设置和真实文件保留策略',btn('保存设置','save-settings','primary'))+`<div class="settings-grid">${panel('输出与缓存',`<label class="label">默认输出目录</label><input id="settings-output" readonly value="${esc(settings.output_dir||data.storage?.output||'')}">${btn('选择输出目录','pick-default-output')}${btn('打开输出目录','open-output')}<p class="note">新任务使用此目录；历史视频和重新生成保留各自原目录。</p><label class="label">缓存保留</label>${select('cacheDays',[['1','1天'],['7','7天'],['30','30天'],['0','不自动清理']],settings.cacheDays)}${btn('按保存策略清理','cleanup')}<p class="note">当前缓存 ${bytes(data.storage?.cache||0)}；缓存是生成过程中的临时文件，原始素材永不自动删除。</p>`)}${panel('默认生产设置',`<label>文案语言<select data-default-language>${options([['th','泰文'],['en','英文']],d.local_copy?.language||'th')}<option value="zh" disabled>中文（预留，未开放）</option></select></label><label>视频尺寸<select data-default-resolution>${options((data.resolution_options||[]).map(r=>[r.id,r.name]),d.resolution||'1080x1920')}</select></label><p class="note">完整显示整张图片；方图放入竖屏时允许上下留空，不裁切、不拉伸。</p><label class="label">音乐方式</label>${select('music',musicModes,settings.music)}<p class="note">无音乐可独立生产；指定单曲或多曲需先在音乐中心选择歌曲。AI等待接入。</p>${btn('查看或编辑全部生产设置','create-task')}${go('管理转场效果','transitions')}${go('管理音乐','music')}${go('管理关键词与泰英文本','local')}`)}${panel('文件保留',`<label class="label">店铺下载素材</label>${select('download_retention',[['keep','保留'],['after_tasks','相关任务全部成功后删除']],settings.download_retention||'keep')}<label class="label">输出视频</label>${select('output_retention',[['keep','保留'],['after_uploaded','所有发布任务真实上传完成后删除'],['after_published','所有发布任务真实发布成功后删除']],settings.output_retention||'keep')}<p class="note">待执行、运行、失败待重试的素材受保护。没有真实上传结果不会触发输出删除。删除后仍保留记录。</p>`)}${panel('外部服务',`<p>TikTok连接、采集、下载、上传：等待真实浏览器环境。</p><p>AI文案、AI选曲、Pixabay搜索下载：等待接入。</p><button disabled title="服务尚未接入">连接执行不可用</button>`)}</div>`};
function musicPage(){
 const all=data.assets.filter(a=>a.kind==='music');
 const shown=all.filter(a=>searchable(a.name,a.metadata?.title,a.metadata?.author,a.metadata?.tags));
 return heading('音乐中心','导入、试听和管理同一素材库中的音乐；未知作者、来源与授权不作推测',btn('导入音乐','import','primary'))+`<div class="toolbar">${search('搜索曲名、文件名、作者或标签…')}${btn('用于任务','use-music','primary',!selectedMusic.size)}</div><p class="note">已选 ${selectedMusic.size} 首，按勾选顺序组成音乐池。AI自动找歌、Pixabay搜索下载等待接入。</p>`+panel('统一音乐库',rowtable(['选择','音乐名称','作者 / 时长','来源 / 授权','试听','操作'],shown.map(a=>`<tr><td><input type="checkbox" data-select="music" value="${a.id}" aria-label="选择音乐 ${esc(a.name)}" ${selectedMusic.has(a.id)?'checked':''} ${!a.available?'disabled':''}></td><td><b>${esc(a.metadata?.title||a.name)}</b><small class="row-sub">${esc(a.name)}</small><details><summary>音乐编号</summary><span>${a.id}</span></details><small class="row-sub"></small></td><td>${esc(a.metadata?.author||'未知')}<br>${Number(a.metadata?.duration||0).toFixed(1)}秒</td><td>${esc(sourceLabel(a.source))}<small class="row-sub">${esc(a.metadata?.source_url||'未提供来源链接')}<br>${esc(a.metadata?.license||'未提供授权信息')}</small></td><td>${a.available?`<audio controls preload="none" src="${media(a)}" aria-label="试听 ${esc(a.name)}"></audio>`:'文件已清理或缺失'}</td><td>${btn('信息','music-info:'+a.id,'link')}${btn('使用历史','music-history:'+a.id,'link')}${btn('删除副本','delete-music:'+a.id,'danger',!a.available)}</td></tr>`).join(''),'尚未导入音乐'));
}
function contentFields(c){return `<label>视频标题<input id="copy-title" value="${esc(c.title||'')}"></label><label>发布说明<textarea id="copy-caption">${esc(c.caption||'')}</textarea></label><label>#标签<input id="copy-tags" value="${esc(c.tags||'')}"></label><label>开头文案<input id="copy-opening" value="${esc(c.opening||'')}"></label><label>行动提示<input id="copy-cta" value="${esc(c.cta||'')}"></label><label>封面文字<input id="copy-cover" value="${esc(c.cover||'')}"></label><label>发布商品关联<select id="copy-association">${options([['none','不关联商品'],['source','使用来源商品'],['selected','指定商品']],c.association||'none')}</select></label><select id="copy-products" multiple aria-label="指定发布商品">${data.products.map(p=>`<option value="${esc(p.id)}" ${(c.product_ids||[]).includes(p.id)?'selected':''}>${esc(p.id)} · ${esc(p.title)}</option>`).join('')}</select><p class="note">来源与发布挂载分开保存；平台实际挂载能力等待验证。本地文案在创建任务中自动生成；此处非空文字作为手动覆盖。AI增强等待接入。</p><button disabled title="AI服务尚未接入">AI生成文案（等待接入）</button>`}
function readContent(){return {title:value('copy-title')||'',caption:value('copy-caption')||'',tags:value('copy-tags')||'',opening:value('copy-opening')||'',cta:value('copy-cta')||'',cover:value('copy-cover')||'',association:value('copy-association')||'none',product_ids:[...(document.getElementById('copy-products')?.selectedOptions||[])].map(e=>e.value)}}
function videoDetails(v){const t=videoTask(v),cfg=JSON.parse(t.config),c=JSON.parse(v.content||'{}'),check=JSON.parse(v.validation||'{}'),m=cfg.music_snapshot;
 return panel('实际配置与发布文字',`<div class="two-fields"><div><p>转场效果：${esc(transitionSummary(taskTransitions(cfg)))}</p><p>实际切换顺序：${esc(transitionSummary(cfg.transition_sequence||taskTransitions(cfg)))}</p><p>视频尺寸：${esc(resolutionLabel(cfg))} · ${esc(cfg.ratio||'9:16')}</p><p>图片适配：完整显示 · 等比例留白，不裁切、不拉伸</p><p>每张图片展示时间：${esc((cfg.durations||[]).join('、'))} 秒</p><p>视频总时长：${Number(cfg.expected_duration||v.duration).toFixed(2)} 秒</p><p>音乐：${esc(m?.title||m?.filename||'无音乐')}<br>来源：${esc(sourceLabel(m?.source))}<br>来源链接：${esc(m?.source_url||'未提供')}<br>授权：${esc(m?.license||'未提供')}</p>${cfg.music_id?`<details><summary>音乐编号</summary><p>${esc(cfg.music_id)}</p></details>`:''}<p>系统检查：${check.status==='passed'?'完整解码及输出参数检查通过':'此视频尚无完整自动检查记录'}</p><p>来源商品：${esc([...new Set((cfg.source_relations||[]).map(r=>r.product_id))].join('、')||'无商品来源')}</p><p>输出：${esc(v.resolved_path||v.path)}</p></div><div>${localTrace(cfg)}<p>标题：${esc(c.title||'未填写')}</p><p>发布说明：${esc(c.caption||'未填写')}</p><p>话题标签：${esc(c.tags||'未填写')}</p><p>开头文案：${esc(c.opening||'未填写')}</p><p>行动提示：${esc(c.cta||'未填写')}</p><p>封面文字：${esc(c.cover||'未填写')}</p><p>发布关联：${associationNames[c.association||'none']||'未记录'} ${esc((c.product_ids||[]).join('、'))}</p>${btn('编辑发布文字与关联','edit-copy:'+v.id)}${btn('打开所在目录','open-folder:'+v.id,'',!v.available)}</div></div>`);
}
const closeModal=()=>document.getElementById('dialog').close();
function productForm(p={}){modal(p.id?'编辑商品':'新建商品',`<div class="two-fields"><div class="field"><label class="label" for="product-id">商品编号 *</label><input id="product-id" required maxlength="150" value="${esc(p.id||'')}" ${p.id?'readonly':''}></div><div class="field"><label class="label" for="store">店铺</label><input id="store" value="${esc(p.store||'')}" placeholder="可留空"></div></div><div class="field"><label class="label" for="product-title">商品标题 *</label><input id="product-title" required maxlength="1000" value="${esc(p.title||'')}"></div><div class="field"><label class="label" for="product-link">商品链接</label><input id="product-link" value="${esc(p.url||'')}" placeholder="可留空"></div><div class="field"><label class="label" for="sku">商品规格（每行一个）</label><textarea id="sku">${data.skus.filter(s=>s.product_id===p.id).map(s=>esc(s.name)).join('\n')}</textarea></div><label>商品详情（原始资料）<textarea id="product-details">${esc(p.details||'')}</textarea></label><label>已确认品类<input id="product-category" value="${esc(p.category||'')}"></label><label>已有关键词<textarea id="product-keywords">${esc(p.keywords||'')}</textarea></label><label>已有视频标题（仅整理检索，不作为商品功能证据）<textarea id="product-video-titles">${esc(p.video_titles||'')}</textarea></label><p class="note">已有 商品规格 及历史视频关联保留，新填写的 商品规格 将追加。</p>`,btn('取消','close')+btn('保存商品','submit-product','primary'))}
let batchDraft=null,batchSeed=0;
const value=id=>document.getElementById(id)?.value;
const selected=name=>[...document.querySelectorAll(`[name="${name}"]:checked`)].map(e=>e.value);
const options=(items,current)=>items.map(([id,label])=>`<option value="${esc(id)}" ${id===current?'selected':''} ${id==='ai'?'disabled':''}>${esc(label)}</option>`).join('');
function batchModal(){
 const draft=batchDraft||settings.production||{};
 batchSeed=Math.floor(Math.random()*2147483647);
 const product=settings.source!=='local',local=draft.local_copy||{};
 const choices=product?data.products:data.assets.filter(a=>a.kind!=='music'&&a.available);
 const chosen=product?selectedProducts:selectedAssets;
 const effects=(draft.transitions||['none']).filter(id=>(data.transitions||[]).some(t=>t.id===id));
 const music=draft.music||settings.music||'none';
 modal('创建生产任务',`
 <p class="dialog-description">简单模式：选择商品或素材后即可开始。其余设置有默认值；需要时再展开高级设置。</p>
 <div class="two-fields"><label>素材来源<select id="batch-source">${options([['products','商品库'],['local','本地素材']],product?'products':'local')}</select></label><label>生成视频数量<input type="number" min="1" max="10000" step="1" id="batch-count-number" value="${draft.count||1}"><small class="note">这是本批总数量。多个商品分别生成时，按所选商品顺序分配。</small></label></div>
 <p class="group-label">选择${product?'商品':'素材'} <span class="required">*</span></p><div class="actions">${btn('全选','batch-all')}${btn('取消全选','batch-none')}</div>
 <div class="choice-list" id="batch-objects" tabindex="-1">${choices.map(o=>`<label><input type="checkbox" name="batch-object" value="${esc(o.id)}" ${chosen.has(o.id)?'checked':''}><span>${esc(o.title||o.name)}</span>${product?`<select data-sku-for="${esc(o.id)}" aria-label="${esc(o.title)} 的商品规格"><option value="">整个商品</option>${data.skus.filter(x=>x.product_id===o.id).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select>`:''}</label>`).join('')||'<p>没有可用对象，请先导入素材或添加商品。</p>'}</div>
 <p class="group-label">转场效果</p><div class="transition-choices" id="batch-transitions" tabindex="-1">${(data.transitions||[]).map(t=>`<div><label><input type="checkbox" name="batch-transition" value="${esc(t.id)}" ${effects.includes(t.id)?'checked':''}><span>${esc(t.name)}<small>${esc(t.description)}</small></span></label>${btn('预览','preview-transition:'+t.id,'link')}</div>`).join('')}</div><p id="batch-transition-order" class="note"></p><div id="batch-transition-preview" aria-live="polite"></div>
 <div class="two-fields"><label>视频尺寸<select id="batch-resolution">${options((data.resolution_options||[]).map(r=>[r.id,r.name]),draft.resolution||'1080x1920')}</select></label><label>文案语言<select id="local-language">${options([['th','泰文'],['en','英文']],local.language||'th')}<option value="zh" disabled>中文（预留，未开放）</option></select></label></div>
 <p class="note">完整显示：图片保持原始比例，完整放入画布；方图放入竖屏时上下留空。不会裁切或拉伸商品。</p>
 <label>音乐方式<select id="batch-music">${options(musicModes,music)}</select></label><p class="note">默认可无音乐生产。本地匹配只使用关键词和音乐标签；没有匹配项会明确提示，绝不调用AI或联网找歌。</p>
 <div id="batch-song-pool" tabindex="-1"><p class="note">勾选歌曲组成音乐池，顺序按勾选先后保存。</p><div class="choice-list">${data.assets.filter(a=>a.kind==='music'&&a.available).map(a=>`<label><input type="checkbox" name="batch-song" value="${a.id}" ${(draft.music_ids||settings.music_ids||[...selectedMusic]).includes(a.id)?'checked':''}><span>${esc(a.metadata?.title||a.name)}</span><audio controls preload="none" src="${media(a)}" aria-label="试听 ${esc(a.name)}"></audio></label>`).join('')||'<p>音乐库为空，请先导入音乐，或选择无音乐。</p>'}</div></div>
 <details id="batch-advanced"><summary>高级设置 <span class="note">时长、组合、顺序、关键词及输出目录</span></summary>
 <label>批次名称<input id="task-name" value="${esc(draft.name||'')}" placeholder="留空自动命名"></label>
 <div class="two-fields"><label>商品／素材组合<select id="group-mode">${options([['individual',product?'每个商品分别生成':'每份素材分别生成'],['group',product?'所选商品合为一个合集':'所选素材合为一组']],draft.group_mode||(product?'individual':'group'))}</select><small class="note">分别生成不会混入其他商品的图片；合集使用所有选定对象。</small></label><label>素材顺序<select id="batch-order">${options([['selected','按下方指定顺序'],['reverse','反向排列'],['random','本次选定素材内随机排列']],draft.order||'selected')}</select></label></div>
 <div class="two-fields"><label>展示时间设置<select id="batch-timing">${options([['images','按每张图片展示时间'],['total','按视频总时长均分']],draft.timing||'images')}</select></label><label>视频总时长（秒）<input type="number" min="0.1" step="0.1" id="batch-total" value="${draft.total_duration||15}"></label></div>
 <label>每张图片展示时间（秒）<input type="number" min="0.034" max="600" step="any" id="batch-seconds" value="${draft.timing==='total'?'':draft.image_duration??2}"><small class="note">默认2秒；下方单图值优先。转场重叠时间会从总时长扣除，两种时长设置不可同时指定。</small></label>
 <div id="batch-assets"></div>
 <div class="two-fields"><label>转场持续时间（秒）<input type="number" min="0" step="0.1" id="batch-transition-time" value="${draft.overrides?.transition_duration??.3}"><small class="note">默认0.3秒，须短于相邻图片的展示时间；直接切换不占转场时间。</small></label><label>画面运动<select id="batch-motion">${options(Object.entries(motionNames),draft.overrides?.motion||'none')}</select><small class="note">默认静止；轻微运动仍保持整张图片在画布内。</small></label></div>
 <div class="two-fields"><label>多曲分配<select id="batch-music-order">${options([['cycle','按勾选顺序循环'],['random','随机打乱，尽量避免相邻重复']],draft.music_order||settings.music_order||'cycle')}</select></label><label>音乐长度<select id="batch-playback">${options([['loop','循环至视频结束'],['trim','播放一次，短于视频则补静音']],draft.music_playback||'loop')}</select></label></div>
 <div class="two-fields"><label>音乐音量（0～1）<input type="number" min="0" max="1" step="0.05" id="batch-volume" value="${draft.overrides?.music_volume??.65}"><small class="note">默认0.65，0为静音，1为原音量。</small></label><label>音乐淡入、淡出各几秒<input type="number" min="0" step="0.1" id="batch-fade" value="${draft.music_fade||0}"><small class="note">默认0秒，不做淡入淡出。</small></label></div>
 ${localBatchFields(local)}<details><summary>手动文字及发布商品关联（可选）</summary>${contentFields(draft.content||{})}</details>
 <label>本次输出目录<input id="batch-output" readonly value="${esc(draft.output_dir||settings.output_dir||data.storage.output)}"><small class="note">默认使用全局输出目录；改动只影响本次及按此配置重新生成的视频。</small></label>${btn('选择目录','pick-batch-output')}
 </details><div id="batch-count" class="info-banner"></div><div id="batch-preview" class="note"></div>`,
 `<p id="batch-missing" class="missing-fields" role="status"></p>`+btn('保存为默认设置','save-production')+btn('检查预计结果','preview-batch')+btn('取消','close')+btn('创建并开始生产','submit-batch','primary',!choices.length));
 document.getElementById('batch-transitions').dataset.order=JSON.stringify(effects);
 document.getElementById('batch-count-number').dataset.manual=draft.count?'true':'false';
 const songOrder=[...(draft.music_ids||settings.music_ids||[...selectedMusic])];
 document.getElementById('batch-music').dataset.songOrder=JSON.stringify(songOrder);
 refreshBatchAssets(draft);refreshLocalPool(local.text_ids||[]);
 document.getElementById('batch-source').addEventListener('change',e=>{settings.source=e.target.value;batchDraft=null;closeModal();batchModal()});
 document.querySelectorAll('[name=batch-object],[data-sku-for]').forEach(e=>e.addEventListener('change',()=>refreshBatchAssets()));
 document.querySelectorAll('#group-mode,#batch-count-number,#batch-timing,#batch-music').forEach(e=>e.addEventListener('change',updateBatchCount));
 document.getElementById('batch-count-number').addEventListener('input',e=>{e.target.dataset.manual='true';updateBatchCount()});
 document.getElementById('batch-timing').addEventListener('change',()=>{if(value('batch-timing')==='total'&&(value('batch-seconds')!==''||[...document.querySelectorAll('[data-duration]')].some(e=>e.value!=='')))toast('切换总时长前，请清空统一展示时间和单图时间；不会静默覆盖已填设置。')});
 document.querySelectorAll('[name=batch-transition]').forEach(e=>e.addEventListener('change',()=>{const box=document.getElementById('batch-transitions');const order=JSON.parse(box.dataset.order);const i=order.indexOf(e.value);if(i>=0)order.splice(i,1);if(e.checked)order.push(e.value);box.dataset.order=JSON.stringify(order);updateBatchCount()}));
 document.querySelectorAll('[name=batch-song]').forEach(e=>e.addEventListener('change',()=>{const i=songOrder.indexOf(e.value);if(i>=0)songOrder.splice(i,1);if(e.checked)songOrder.push(e.value);document.getElementById('batch-music').dataset.songOrder=JSON.stringify(songOrder);updateBatchCount()}));
 updateBatchCount();
}
function batchVisuals(){
 const ids=selected('batch-object');
 if(value('batch-source')==='local')return ids.map(getAsset).filter(Boolean);
 const result=[];
 for(const id of ids){const sku=[...document.querySelectorAll('[data-sku-for]')].find(e=>e.dataset.skuFor===id)?.value;
  for(const l of data.links.filter(l=>l.product_id===id&&(!sku||!l.sku_id||l.sku_id===sku)).sort((a,b)=>a.position-b.position)){
   const a=getAsset(l.asset_id);if(a?.kind!=='music'&&a?.available&&!result.some(x=>x.id===a.id))result.push(a);
  }
 }
 return result;
}
function refreshBatchAssets(draft={}){
 const old={...draft.asset_durations};document.querySelectorAll('[data-duration]').forEach(e=>{if(e.value!=='')old[e.dataset.duration]=e.value});
 const list=batchVisuals();
 document.getElementById('batch-assets').innerHTML=rowtable(['素材','顺序','单独秒数（留空用统一值）'],list.map((a,i)=>`<tr><td>${esc(a.name)}</td><td><input type="number" min="1" data-order="${a.id}" aria-label="${esc(a.name)}顺序" value="${(draft.asset_order||[]).includes(a.id)?draft.asset_order.indexOf(a.id)+1:i+1}"></td><td><input type="number" min="0.034" max="600" step="any" data-duration="${a.id}" aria-label="${esc(a.name)}秒数" value="${old[a.id]??''}"></td></tr>`).join(''),'选择对象后显示实际素材');
 updateBatchCount();
}
function batchMissing(requireObjects=true){
 const count=Number(value('batch-count-number')),ids=selected('batch-object'),n=value('group-mode')==='group'?(ids.length?1:0):ids.length;
 const missing=[];
 if(requireObjects&&!ids.length)missing.push(['请先选择商品或素材','batch-objects']);
 if(!Number.isInteger(count)||count<1||count>10000)missing.push(['生成视频数量须为1～10000的整数','batch-count-number']);
 else if(count<n)missing.push([`分别生成${n}个对象至少需要${n}条视频，请增加数量或改为合集`,'batch-count-number']);
 if(!selected('batch-transition').length)missing.push(['请选择至少一种转场效果','batch-transitions']);
 if(value('batch-music')==='ai'||value('local-mode')==='ai')missing.push(['AI尚未接入，请选择本地方式','batch-music']);
 const songs=selected('batch-song');
 if(value('batch-music')==='single'&&songs.length!==1)missing.push(['指定单曲需要勾选一首音乐','batch-song-pool']);
 if(value('batch-music')==='multi'&&!songs.length)missing.push(['多曲方式需要勾选音乐','batch-song-pool']);
 return missing;
}
function updateBatchCount(){
 if(!document.getElementById('batch-count-number'))return;
 const n=value('group-mode')==='group'?(selected('batch-object').length?1:0):selected('batch-object').length;
 const count=document.getElementById('batch-count-number');if(count.dataset.manual!=='true')count.value=Math.max(1,n);
 document.getElementById('batch-count').textContent=`已选择${n}个生产对象，本批生成${Number(count.value)||0}条视频。分别生成时顺序分配数量，各对象素材独立。`;
 const order=JSON.parse(document.getElementById('batch-transitions').dataset.order||'[]');
 document.getElementById('batch-transition-order').textContent=order.length?'切换顺序：'+transitionSummary(order)+(order.length>1?'，按此顺序循环':'，全片统一使用'):'请至少选择一种转场效果。';
 document.getElementById('batch-total').disabled=value('batch-timing')!=='total';
 document.getElementById('batch-song-pool').hidden=!['single','multi'].includes(value('batch-music'));
 const missing=batchMissing();document.getElementById('batch-missing').textContent=missing.map(([message])=>message).join('；');
 const submit=document.querySelector('[data-action="submit-batch"]');if(submit)submit.disabled=!!missing.length;
}
function readBatch(requireObjects=true){
 const error=document.getElementById('dialog-error');if(error){error.hidden=true;error.textContent=''}document.querySelectorAll('[aria-invalid=true]').forEach(e=>e.removeAttribute('aria-invalid'));
 const missing=batchMissing(requireObjects);if(missing.length)throw fieldError(missing[0][0],missing[0][1]);
 const ids=selected('batch-object'),product=value('batch-source')==='products',group=value('group-mode')==='group';
 const sku=id=>[...document.querySelectorAll('[data-sku-for]')].find(e=>e.dataset.skuFor===id)?.value||null;
 if(product&&group&&ids.some(id=>sku(id)))throw fieldError('商品合集使用整个商品；请清除单规格选择后创建','batch-objects');
 const objects=product?(group?[{product_ids:ids}]:ids.map(id=>({product_id:id,sku_id:sku(id)}))):(group?[{assets:ids}]:ids.map(id=>({assets:[id]})));
 const durations=Object.fromEntries([...document.querySelectorAll('[data-duration]')].filter(e=>e.value!=='').map(e=>[e.dataset.duration,Number(e.value)]));
 const timing=value('batch-timing');
 if(timing==='total'&&(value('batch-seconds')!==''||Object.keys(durations).length))throw fieldError('视频总时长与已填图片展示时间冲突。请清空统一和单图时间后使用总时长，或切回按图片展示时间。','batch-seconds');
 for(const e of document.querySelectorAll('#batch-count-number,#batch-seconds,#batch-total,#batch-transition-time,#batch-volume,#batch-fade,[data-duration],[data-order]'))if(!e.disabled&&!e.checkValidity())throw fieldError('请检查“'+(e.closest('label')?.childNodes[0]?.textContent||e.getAttribute('aria-label')||'时间设置')+'”的有效范围',e.id||'batch-assets');
 const checked=selected('batch-song'),songOrder=JSON.parse(document.getElementById('batch-music').dataset.songOrder||'[]');
 return {seed:batchSeed,name:value('task-name'),objects,transitions:JSON.parse(document.getElementById('batch-transitions').dataset.order),resolution:value('batch-resolution'),fit:'contain',count:Number(value('batch-count-number')),group_mode:value('group-mode'),order:value('batch-order'),asset_order:[...document.querySelectorAll('[data-order]')].sort((a,b)=>Number(a.value)-Number(b.value)).map(e=>e.dataset.order),timing,total_duration:timing==='total'?Number(value('batch-total')):undefined,image_duration:value('batch-seconds')===''?undefined:Number(value('batch-seconds')),asset_durations:durations,overrides:{transition_duration:Number(value('batch-transition-time')),motion:value('batch-motion'),music_volume:Number(value('batch-volume'))},music:value('batch-music'),music_ids:[...new Set([...songOrder.filter(id=>checked.includes(id)),...checked])],music_order:value('batch-music-order'),music_playback:value('batch-playback'),music_fade:Number(value('batch-fade')),output_dir:value('batch-output'),local_copy:readLocalBatch(),content:readContent()};
}
actions=async function(action){try{
 if(action==='reconnect'){await loadState();return}
 if(!online && !action.startsWith('go:')){toast('本地工作空间尚未连接');return}
 if(action==='help'){modal('从商品到视频',`<ol class="rules"><li>在商品库新建或导入商品；本地素材可以不绑定商品。</li><li>导入图片、视频和音乐，按需关联商品。</li><li>选定商品或素材，选择转场效果和数量后创建批量任务。</li><li>在视频管理预览、追溯、重新生成或加入发布队列。</li><li>真实 TikTok 环境接入后再执行同步和发布。</li></ol>`);return}
 if(action.startsWith('focus-product:')){productFocus=action.slice(14);render();return}
 if(action.startsWith('focus-video:')){videoFocus=action.slice(12);render();return}
 if(action==='new-product'){productForm();return}
 if(action.startsWith('edit-product:')){productForm(getProduct(action.slice(13)));return}
 if(action==='submit-product'){const value=id=>document.getElementById(id).value.trim();const id=value('product-id'),title=value('product-title');if(!id)throw fieldError('请填写商品编号','product-id');if(!title)throw fieldError('请填写商品标题','product-title');await api('product',{id,title,store:value('store'),url:value('product-link'),skus:value('sku').split('\n'),details:value('product-details'),category:value('product-category'),keywords:value('product-keywords'),video_titles:value('product-video-titles')});closeModal();productFocus=id;await loadState();toast('商品已保存');return}
 if(action==='import-products'){modal('导入商品 CSV',`<p class="dialog-description">CSV 表头：id、title、store、url、skus。id 与 title 必填；多个 商品规格 使用 | 分隔。相同商品编号 更新信息并保留历史关联。</p>`,btn('取消','close')+btn('选择 CSV 文件','pick-products','primary',false,'folder'));return}
 if(action==='pick-products'){closeModal();const r=await api('import-products',{});if(r.cancelled){toast('已取消选择');return}await loadState();toast(`已导入 ${r.count} 个商品`);return}
 if(['import','import-folder'].includes(action)){const r=await api('import',{folder:action==='import-folder'});if(r.cancelled){toast('已取消选择');return}await loadState();if(r.errors.length){modal('素材导入结果',`<p class="dialog-description">识别 ${r.ids.length} 份有效素材，${r.errors.length} 份未导入。</p><div class="import-result">${r.errors.map(e=>`<p><b>${esc(e.name)}</b><br>${esc(e.error)}</p>`).join('')}</div>`)}else toast(`已识别 ${r.ids.length} 份素材`);return}
 if(action.startsWith('preview-asset:')){const a=getAsset(action.slice(14));modal(esc(a.name),a.kind==='image'?`<img src="${media(a)}" alt="${esc(a.name)}" width="100%">`:a.kind==='music'?`<audio src="${media(a)}" controls></audio>`:`<video src="${media(a)}" controls width="100%"></video>`);return}
 if(action.startsWith('link-assets:')){const pid=action.slice(12);modal('关联素材 · '+esc(pid),`<div class="choice-list">${data.assets.map(a=>`<label><input type="checkbox" name="link-asset" value="${a.id}" ${productAssets(pid).some(x=>x.id===a.id)?'checked disabled':''}><span>${esc(a.name)}</span></label>`).join('')||'<p class="note">请先导入素材。</p>'}</div>`,btn('取消','close')+btn('保存关联','submit-link:'+pid,'primary',!data.assets.length));return}
 if(action.startsWith('submit-link:')){await api('link',{product_id:action.slice(12),ids:[...document.querySelectorAll('[name=link-asset]:checked')].map(e=>e.value)});closeModal();await loadState();toast('素材关联已保存');return}
 if(action==='assets-link'){modal('关联到商品',`<div class="field"><label class="label">目标商品</label><select id="link-product">${data.products.map(p=>`<option value="${esc(p.id)}">${esc(p.id)} · ${esc(p.title)}</option>`).join('')}</select></div><p class="note">将关联 ${selectedAssets.size} 份素材，保留现有商品关系。</p>`,btn('取消','close')+btn('关联','link-selected','primary',!data.products.length));return}
 if(action==='link-selected'){await api('link',{product_id:document.getElementById('link-product').value,ids:[...selectedAssets]});closeModal();await loadState();toast('关联已保存');return}
 if(['create-task','product-tasks','asset-tasks'].includes(action)){if(action==='product-tasks')settings.source='products';if(action==='asset-tasks')settings.source='local';if(settings.source==='tiktok'){toast('等待连接 TikTok 店铺环境');return}batchModal();return}
 if(action==='submit-batch'){const payload=readBatch();const button=document.querySelector('[data-action="submit-batch"]');button.disabled=true;try{const r=await api('batch',payload);batchDraft=null;closeModal();await loadState();location.hash='tasks';toast(`已创建 ${r.tasks} 条任务`)}finally{if(button.isConnected)button.disabled=false}return}
 if(action==='preview-batch'){const r=await api('batch-preview',readBatch());document.getElementById('batch-preview').textContent=r.preview.map((t,i)=>`第${i+1}条：${t.config.expected_duration.toFixed(3)}秒，${resolutionLabel(t.config)}，${transitionSummary(taskTransitions(t.config))}，音乐 ${t.config.music_snapshot?.title||t.config.music_snapshot?.filename||'无'} ${t.config.music_match?.status==='unmatched'?'（未匹配，请调整音乐方式）':''}，${t.config.publication_content?.title||''}，${languageNames[t.config.text_trace?.language]||'手动文字'}，${t.config.text_trace&&Object.values(t.config.text_trace.fallback).some(Boolean)?'含通用文案兜底':'使用所选文案'}；${(t.config.text_trace?.unmatched||[]).map(displayReason).join('；')}`).join('；');document.getElementById('batch-preview').scrollIntoView({block:'nearest'});return}
 if(action==='save-production'){const payload=readBatch(false);const {objects,seed,asset_order,asset_durations,...defaults}=payload;await api('settings',{production:defaults,music:payload.music,music_ids:payload.music_ids,music_order:payload.music_order});await loadState(false);toast('默认设置已保存；每次生产单独选择商品或素材');return}
 if(action==='batch-all'||action==='batch-none'){document.querySelectorAll('[name=batch-object]').forEach(e=>e.checked=action==='batch-all');refreshBatchAssets();return}
 if(action==='pick-batch-output'||action==='pick-default-output'){const r=await api('choose-output',{});if(r.cancelled){toast('已取消选择');return}if(action==='pick-batch-output')document.getElementById('batch-output').value=r.path;else{settings.output_dir=r.path;document.getElementById('settings-output').value=r.path}return}
 if(action.startsWith('choose-transition:')){const id=action.slice(18),selected=[...(settings.production?.transitions||['none'])],index=selected.indexOf(id);if(index>=0){if(selected.length===1){toast('请至少保留一种转场效果');return}selected.splice(index,1)}else selected.push(id);settings.production={...settings.production,transitions:selected};render();toast('转场已选择；点击“保存为默认”可保存');return}
 if(action.startsWith('preview-transition:')){
  const id=action.slice(19),effect=(data.transitions||[]).find(t=>t.id===id);if(!effect)throw Error('转场效果不存在');
  const batch=!!document.getElementById('batch-source'),payload={transition:id,resolution:batch?value('batch-resolution'):'1080x1920',transition_duration:batch?Number(value('batch-transition-time')):.3};
  if(!batch)modal(esc(effect.name)+' · 实际效果',`<div id="transition-preview" aria-live="polite"></div>`);
  const target=document.getElementById(batch?'batch-transition-preview':'transition-preview');target.innerHTML='<p>正在准备实际效果预览…</p>';target.scrollIntoView({block:'nearest'});
  try{const result=await api('transition-preview',payload);if(target.isConnected)target.innerHTML=`<p>${esc(effect.name)} · 两张示意图各展示2秒，使用当前尺寸与转场时间。</p><video controls preload="metadata" src="${esc(result.url)}" aria-label="${esc(effect.name)}实际转场预览"></video>`}catch(error){if(target.isConnected)target.innerHTML='';throw error}return;
 }
 if(action==='use-music'){settings.music=selectedMusic.size===1?'single':'multi';settings.music_ids=[...selectedMusic];settings.production={...settings.production,music:settings.music,music_ids:settings.music_ids};await api('settings',{music:settings.music,music_ids:settings.music_ids,production:settings.production});batchDraft=null;batchModal();return}
 if(action.startsWith('music-info:')){const a=getAsset(action.slice(11));modal('音乐信息（只填写已知资料）',`${['title','author','source_url','license','tags'].map((k,i)=>`<label>${['曲名','作者','来源链接','授权信息','标签'][i]}<input id="music-${k}" value="${esc(a.metadata?.[k]||'')}"></label>`).join('')}<details><summary>音乐编号</summary><p>${a.id}</p></details>`,btn('取消','close')+btn('保存','save-music:'+a.id,'primary'));return}
 if(action.startsWith('save-music:')){await api('music-metadata',{id:action.slice(11),values:Object.fromEntries(['title','author','source_url','license','tags'].map(k=>[k,value('music-'+k)]))});closeModal();await loadState();return}
 if(action.startsWith('music-history:')){const id=action.slice(14);const tasks=data.tasks.filter(t=>JSON.parse(t.config).music_id===id);modal('音乐使用历史',rowtable(['任务','状态','保存的曲名与来源'],tasks.map(t=>{const m=JSON.parse(t.config).music_snapshot;return `<tr><td>${esc(taskLabel(t))}</td><td>${statusBadge(t.status)}</td><td>${esc(m?.title||getAsset(id)?.name||id)}<br>${esc(m?.source_url||'未提供来源链接')}</td></tr>`}).join(''),'尚未用于任务'));return}
 if(action.startsWith('delete-music:')){const id=action.slice(13);modal('删除音乐副本',`<p>保留用户原文件和使用历史。待执行、运行或待重试任务使用的音乐不能删除。</p>`,btn('取消','close')+btn('删除副本','confirm-delete-music:'+id,'danger'));return}
 if(action.startsWith('confirm-delete-music:')){const id=action.slice(21);await api('delete-asset',{id});selectedMusic.delete(id);closeModal();await loadState();return}
 if(action.startsWith('edit-copy:')){const v=getVideo(action.slice(10));modal('发布文字与商品关联',contentFields(JSON.parse(v.content||'{}')),btn('取消','close')+btn('保存','save-copy:'+v.id,'primary'));return}
 if(action.startsWith('save-copy:')){await api('content',{id:action.slice(10),content:readContent()});closeModal();await loadState();return}
 if(action.startsWith('open-folder:')){await api('open',{id:action.slice(12),folder:true});return}
 if(action==='queue-selected'){modal('加入发布队列',`<label>目标账号／店铺（仅保存配置）<input id="queue-target"></label><p>将保存 ${selectedVideos.size} 条视频及各自文案。真实上传与发布等待接入。</p>`,btn('取消','close')+btn('保存队列','confirm-queue','primary'));return}
 if(action==='confirm-queue'){for(const id of selectedVideos)await api('queue',{id,target:value('queue-target')});closeModal();await loadState();toast('队列已保存，等待真实连接');return}

 if(action.startsWith('retry:')){await api('retry',{id:action.slice(6)});await loadState();return}
 if(action.startsWith('regenerate:')){await api('regenerate',{id:action.slice(11)});await loadState();toast('已按原始配置创建新视频任务');return}
 if(action.startsWith('open-video:')){await api('open',{id:action.slice(11)});return}
 if(action==='open-output'){await api('open',{});return}
 if(action==='trash-selected'){modal('移入回收站',`<p class="dialog-description">将 ${selectedVideos.size} 条视频移入回收站。输出文件暂时保留，原始素材不受影响。</p>`,btn('取消','close')+btn('移入回收站','confirm-trash','danger'));return}
 if(action==='confirm-trash'){for(const id of selectedVideos)await api('trash',{id});selectedVideos.clear();closeModal();await loadState();return}
 if(action.startsWith('restore:')){await api('trash',{id:action.slice(8),restore:true});await loadState();return}
 if(action==='cleanup'){const r=await api('cleanup',{});await loadState();toast('已清理 '+bytes(r.bytes)+' 缓存');return}
 if(action==='export-videos'){const header=['视频编号','商品编号','商品规格','转场效果','视频尺寸','图片适配','生产任务','文件路径','生成时间'];const rows=data.videos.map(v=>{const t=videoTask(v),cfg=JSON.parse(t.config);return[v.id,t.product_id,getSku(t.sku_id),transitionSummary(taskTransitions(cfg)),resolutionLabel(cfg),'完整显示',taskLabel(t),v.resolved_path||v.path,v.created]});const csv='\ufeff'+[header,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='TikTokVideoMaker_videos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 return await oldActions(action);
}catch(e){reportError(e)}};
document.addEventListener('change',e=>{const kind=e.target.dataset.select;if(kind){const set=kind==='product'?selectedProducts:kind==='asset'?selectedAssets:kind==='music'?selectedMusic:selectedVideos;e.target.checked?set.add(e.target.value):set.delete(e.target.value);render()}if(e.target.id==='store-filter'){storeFilter=e.target.value;render()}if(e.target.id==='production-filter'){productStatus=e.target.value;render()}if(e.target.id==='asset-source'){assetSource=e.target.value;render()}if(e.target.id==='asset-relation'){assetRelation=e.target.value;render()}});
