setInterval(async()=>{if(!['home','tasks','videos','publish'].includes(route)||!online||document.getElementById('dialog').open||document.querySelector('video')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;try{const before=JSON.stringify(data);await loadState(false);if(before!==JSON.stringify(data))render()}catch(e){online=false;toast(e.message+'；可点击重试连接')}},2000);
loadState().catch(e=>{online=false;document.getElementById('page').innerHTML=panel('本地工作空间未连接',`<div class="offline"><h3>请从 TikTokVideoMaker 桌面程序启动</h3><p class="note">${esc(e.message)}</p>${btn('重试连接','reconnect')}</div>`)});
shops=function(){const rules=data.download_rules||[];return heading('店铺商品','选择店铺与商品范围，应用图片下载规则后同步到统一素材中心',`<span class="status waiting">等待连接 TikTok 店铺环境</span>`)+`<div class="info-banner">${icon('clock')}当前仅保存同步配置。没有连接真实环境，不会采集商品或下载图片。</div><div class="settings-grid">${panel('商品同步配置',`<div class="field"><label class="label" for="sync-store">待连接店铺</label><input id="sync-store" placeholder="填写店铺名称，仅保存配置"></div><div class="field"><label class="label" for="sync-scope">商品范围</label><select id="sync-scope"><option value="all">全部商品</option><option value="selected">指定商品编号</option></select></div><div class="field"><label class="label" for="sync-ids">指定商品编号（每行一个）</label><textarea id="sync-ids" disabled placeholder="选择指定商品范围后填写"></textarea></div><div class="field"><label class="label" for="sync-rule">图片下载规则</label><select id="sync-rule">${rules.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')||'<option value="">请先保存图片下载规则</option>'}</select></div><div class="actions">${btn('保存待连接配置','save-sync','primary',!rules.length,'check')}${btn('开始同步','','',true,'download')}</div>`)}${panel('图片下载规则',`<div class="field"><label class="label" for="rule-name">规则名称</label><input id="rule-name" placeholder="例如：手机壳视频素材规则"></div><div class="field"><label class="label" for="rule-main">商品主图</label><select id="rule-main"><option value="first">下载第 1 张主图</option><option value="all">下载全部主图</option><option value="custom">自定义选择</option></select></div><div class="field"><label class="label" for="rule-indices">自定义主图序号</label><input id="rule-indices" disabled placeholder="例如：1,3,5"></div><label class="settings-row"><span>全部详情图片</span><input id="rule-details" type="checkbox" checked></label><label class="settings-row"><span>商品规格 图片及对应关系</span><input id="rule-skus" type="checkbox" checked></label><label class="settings-row"><span>商品视频 <small class="note">当前未开放</small></span><input type="checkbox" disabled></label><p class="note">保留商品编号、商品规格编号／名称、图片类型、排序和来源。后续生产直接使用关联素材。</p>${btn('保存下载规则','save-rule','primary',false,'check')}`)}</div>${panel('已保存的图片规则',rowtable(['规则名称','主图','详情图','商品规格 图','商品视频','操作'],rules.map(r=>{const c=JSON.parse(r.config);return `<tr><td>${esc(r.name)}</td><td>${c.main==='first'?'第 1 张':c.main==='all'?'全部主图':'第 '+c.indices.join('、')+' 张'}</td><td>${c.details?'全部':'关闭'}</td><td>${c.sku_images?'开启':'关闭'}</td><td>关闭</td><td>${btn('载入规则','load-rule:'+r.id,'link')}</td></tr>`}).join(''),'尚未保存下载规则'))}${panel('商品同步任务',rowtable(['店铺','商品范围','图片规则','同步状态','创建时间'],(data.sync_tasks||[]).map(t=>{const c=JSON.parse(t.rule_snapshot||'{}'),s=JSON.parse(t.product_scope||'{}');return `<tr><td>${esc(t.store)}</td><td>${s.mode==='all'?'全部商品':esc((s.ids||[]).join('、'))}</td><td>${c.main==='first'?'第 1 张主图':c.main==='all'?'全部主图':esc((c.indices||[]).join('、'))}</td><td><span class="status waiting">等待连接</span></td><td>${esc(t.created)}</td></tr>`}).join(''),'暂无同步配置'))}`};
let editingRule=null;
const productionActions=actions;
actions=async function(action){try{
 if(action==='save-rule'){const mode=document.getElementById('rule-main').value;const text=document.getElementById('rule-indices').value.trim();const indices=mode==='custom'?text.split(/[,，\s]+/).filter(Boolean).map(x=>/^\d+$/.test(x)?Number(x):null):[];if(mode==='custom'&&(!indices.length||indices.some(x=>x===null||!Number.isSafeInteger(x)||x<1))){toast('请输入正整数主图序号，例如 1,3,5');return}await api('download-rule',{id:editingRule,name:document.getElementById('rule-name').value,main:mode,indices,details:document.getElementById('rule-details').checked,sku_images:document.getElementById('rule-skus').checked,product_video:false});editingRule=null;await loadState();toast('图片下载规则已保存');return}
 if(action.startsWith('load-rule:')){const r=data.download_rules.find(r=>r.id===action.slice(10));if(!r)return;editingRule=r.id;const c=JSON.parse(r.config);document.getElementById('rule-name').value=r.name;document.getElementById('rule-main').value=c.main;document.getElementById('rule-indices').value=c.indices.join(',');document.getElementById('rule-indices').disabled=c.main!=='custom';document.getElementById('rule-details').checked=c.details;document.getElementById('rule-skus').checked=c.sku_images;document.getElementById('sync-rule').value=r.id;return}
 if(action==='save-sync'){const scope=document.getElementById('sync-scope').value;await api('sync-request',{store:document.getElementById('sync-store').value,scope:{mode:scope,ids:scope==='all'?[]:document.getElementById('sync-ids').value.split('\n').map(x=>x.trim()).filter(Boolean)},rule_id:document.getElementById('sync-rule').value});await loadState();toast('配置已保存，等待连接真实店铺环境');return}
 return await productionActions(action);
}catch(e){reportError(e)}};
document.addEventListener('change',e=>{if(e.target.id==='rule-main')document.getElementById('rule-indices').disabled=e.target.value!=='custom';if(e.target.id==='sync-scope')document.getElementById('sync-ids').disabled=e.target.value!=='selected'});

window.addEventListener('hashchange',()=>{editingRule=null});

const localKinds=[['pattern','图名关键词'],['material','材质关键词'],['color','颜色关键词'],['keyword','已有关键词'],['text','泰文／英文文本'],['music_rule','音乐标签对应关系']];
const sourceLabels=[['sku_pattern','商品规格图名关键词'],['sku_material','商品规格材质关键词'],['sku_color','商品规格颜色关键词'],['product_title','商品标题关键词'],['product_details','商品详情关键词'],['existing','图名对应资料／已有关键词'],['video_titles','已有视频标题关键词（仅整理检索）']];
const copyFields=[['title','视频标题'],['caption','发布说明'],['tags','话题标签组合'],['opening','开头文案'],['cta','行动提示'],['cover','封面文字']];
const recordLabel=r=>r?.id?.startsWith('builtin_')?String(r.key).replace(/\bth\b/g,'泰文').replace(/\ben\b/g,'英文'):r?.key||'未记录';
function displayReason(message){return String(message).replace(/^(en|th) 的 (title|caption|tags|opening|cta|cover) /,(_,language,field)=>languageNames[language]+'的'+copyFields.find(([key])=>key===field)[1]+' ').replace(/^(pattern|material|color)未唯一匹配：/,(_,kind)=>({pattern:'图名',material:'材质',color:'颜色'}[kind])+'未唯一匹配：').replace(/属性冲突，已省略：(material|color|model|price|promotion|category)$/,(_,kind)=>'属性冲突，已省略：'+({material:'材质',color:'颜色',model:'型号',price:'价格',promotion:'促销',category:'品类'}[kind]))}
let localKind='pattern';
localPage=function(){const rows=(data.local_records||[]).filter(r=>r.kind===localKind&&searchable(recordLabel(r),r.source,languageNames[r.language],r.aliases,r.en,r.th,JSON.stringify(r.body||{})));return heading('本地资料库','资料保存在本软件数据库，删除或更新不会改写已生成视频的历史',btn('批量导入资料文件','import-local')+btn('导出资料','export-local')+btn('新增资料','new-local','primary'))+`<div class="toolbar">${search('搜索匹配键、语言、来源或内容…')}<select id="local-kind" aria-label="资料类型">${options(localKinds,localKind)}</select></div><p class="note">当前共 ${(data.local_records||[]).length} 条记录。图名、材质、颜色和歌曲由你提供；内置通用文本不代表正式商品资料齐全。</p>`+panel('资料记录',rowtable(['匹配键','语言 / 版本','内容','来源','操作'],rows.map(r=>`<tr><td>${esc(recordLabel(r))}<small class="row-sub">别名：${esc((r.aliases||[]).join('、'))||'未填写'}</small></td><td>${languageNames[r.language]||'泰英对应'} / 第${r.version}版</td><td>${r.kind==='text'?copyFields.filter(([k])=>r.body?.[k]).map(([k,n])=>`${n}：${esc(r.body[k])}`).join('<br>'):esc(r.kind==='music_rule'?(r.match_tags||[]).join('、')+' → '+(r.music_tags||[]).join('、'):(r.th||'泰文缺失')+' / '+(r.en||'英文缺失'))}${r.generic?'<small class="row-sub">通用兜底</small>':''}</td><td>${esc(r.source)}</td><td>${btn('查看／修改','edit-local:'+r.id,'link')}${btn('删除','delete-local:'+r.id,'danger')}</td></tr>`).join(''),'此类资料为空'))+panel('批量导入说明',`<p>支持资料文件（JSON或CSV）。先在界面创建一条资料，再导出作为批量文件格式；日常新增、查询和修改都可在此完成。</p><p>更新时保留导出文件中的记录编号与版本，系统核对匹配键、类型和语言。对象不匹配或版本过期会报告失败，不会覆盖另一条资料。</p><p>资料来源填写依据；图名只用于匹配，不会自动写入发布文案。导入后的具体商品规格未匹配和通用兜底原因可在任务“检查预计结果”查看。规则只降低错误风险，不保证平台审核或权利许可。</p>`)};
function localForm(r={kind:localKind}){
 const edit=!!r.id;
 modal(edit?'修改本地资料':'新增本地资料',`<input id="local-id" type="hidden" value="${esc(r.id||'')}"><input id="local-version" type="hidden" value="${r.version||''}"><label>类型<select id="record-kind" ${edit?'disabled':''}>${options(localKinds,r.kind)}</select></label><label>匹配键 <span class="required">*</span><input required id="record-key" value="${esc(r.key?recordLabel(r):'')}" data-original-key="${esc(r.key||'')}" ${edit?'readonly':''}></label><label>来源／依据 <span class="required">*</span><textarea required id="record-source">${esc(r.source||'')}</textarea></label><label>已知别名（逗号分隔）<input id="record-aliases" value="${esc((r.aliases||[]).join(','))}"></label><p class="note">匹配键填写实际图名、材质、颜色或自定文本名称；别名用于识别同一资料的已有叫法，来源记录表达依据。</p><label>本地标签（逗号分隔）<input id="record-tags" value="${esc((r.tags||[]).join(','))}"></label><p class="note">标签用于本地音乐匹配；不会自动证明商品功能。</p><label>限定品类（留空为无品类限制）<input id="record-category" value="${esc(r.category||'')}"></label>${r.kind==='text'?`<label>语言<select id="record-language" ${edit?'disabled':''}>${options([['th','泰文'],['en','英文']],r.language||'th')}</select></label><label><input id="record-generic" type="checkbox" ${r.generic?'checked':''}>通用兜底（不含商品属性、功能、价格、促销、品牌或IP断言）</label><label>必须具备的事实关键词匹配键（逗号分隔）<input id="record-requires" value="${esc((r.requires||[]).join(','))}"></label><p class="note">针对性文案的占位符：关键词 {keywords}、图名词 {pattern}、材质词 {material}、颜色词 {color}、品类 {category}、话题标签 {hashtags}。只会替换为已有资料；缺词使用当前语言通用文案。</p>${copyFields.map(([k,n])=>`<label>${n}<textarea id="record-body-${k}">${esc(r.body?.[k]||'')}</textarea></label>`).join('')}`:r.kind==='music_rule'?`<label>关键词输入标签<input id="record-match" value="${esc((r.match_tags||[]).join(','))}"></label><label>对应音乐标签<input id="record-music" value="${esc((r.music_tags||[]).join(','))}"></label>`:`${r.kind==='keyword'?`<label>属性<select id="record-property">${options([['pattern','图案／风格'],['material','材质'],['color','颜色'],['feature','商品功能'],['category','品类'],['model','适配型号'],['price','价格'],['promotion','促销']],r.property||'pattern')}</select></label>`:''}<label>已确认泰文表达<input id="record-th" value="${esc(r.th||'')}"></label><label>已确认英文表达<input id="record-en" value="${esc(r.en||'')}"></label><label><input id="record-confirmed" type="checkbox" ${r.confirmed?'checked':''}>表达已有资料依据；不从名称推测功能或授权</label>`}`,btn('取消','close')+btn('保存资料','save-local','primary'));
 document.getElementById('record-kind').addEventListener('change',e=>localForm({kind:e.target.value}));
}
function localBatchFields(o){return `<section><h3>本地文案与关键词</h3><label>文案方式<select id="local-mode">${options([['local','本地自动生成'],['manual','仅使用手动文字'],['ai','AI增强（等待接入）']],o.mode||'local')}</select></label><div class="actions">${btn('全部选择','copy-all')}${btn('清空／自定义','copy-none')}</div><p class="note">关键词来源可自由多选；默认未选择时使用对应语言通用文案。未勾选来源不加入文案。</p><div class="choice-list">${sourceLabels.map(([k,n])=>`<label><input type="checkbox" name="copy-source" value="${k}" ${(o.sources||[]).includes(k)?'checked':''}>${n}</label>`).join('')}</div><details><summary>选择已有关键词（需勾选“图名对应资料／已有关键词”）</summary>${(data.local_records||[]).filter(r=>['pattern','material','color','keyword'].includes(r.kind)).map(r=>`<label><input type="checkbox" name="copy-keyword" value="${r.id}" ${(o.keyword_ids||[]).includes(r.id)?'checked':''}>${esc(recordLabel(r))}</label>`).join('')||'尚无关键词资料'}</details><label>文本分配<select id="local-order">${options([['cycle','顺序轮换'],['random','随机打乱']],o.order||'cycle')}</select></label><div id="local-text-pool"></div><p class="note">不选文本池时使用当前语言的可用文本；关键词不足时使用同语言通用文本。开头和封面文字仅保存为发布资料，不强制绘制到视频。</p></section>`}
function refreshLocalPool(chosen=[]){const language=value('local-language');document.getElementById('local-text-pool').innerHTML='<p>文本模板／模板池（可多选）</p>'+(data.local_records||[]).filter(r=>r.kind==='text'&&r.language===language).map(r=>`<label><input type="checkbox" name="copy-text" value="${r.id}" ${chosen.includes(r.id)?'checked':''}>${esc(recordLabel(r))}${r.generic?' · 通用兜底':''}</label>`).join('')}
function readLocalBatch(){return {mode:value('local-mode'),language:value('local-language'),sources:selected('copy-source'),keyword_ids:selected('copy-keyword'),text_ids:selected('copy-text'),order:value('local-order')}}
function localTrace(cfg){const t=cfg.text_trace;return t?`<h3>本地生成依据 · ${languageNames[t.language]||'未记录'}</h3><p>${Object.entries(t.templates).map(([k,r])=>`${copyFields.find(([key])=>key===k)?.[1]||'发布文字'}：${esc(recordLabel(r))} 第${r.version}版${t.fallback[k]?'（通用兜底）':''}`).join('<br>')}</p><details><summary>实际来源与未匹配记录</summary><p>${t.keywords.map(k=>`${esc(k.key)} · ${esc(sourceLabel(k.source))} · ${k.used?'已使用':'已省略或仅供检索'} · ${esc(k.evidence)}`).join('<br>')||'没有可用关键词，已使用通用文本'}</p><p>${[...t.unmatched,...t.omitted].map(x=>esc(displayReason(x))).join('<br>')}</p></details><p>音乐：${musicModes.find(([id])=>id===cfg.music_mode)?.[1]||'未记录'} ${matchNames[cfg.music_match?.status]||''}</p>`:''}
const localActions=actions;
actions=async function(action){try{
 if(action==='copy-all'||action==='copy-none'){document.querySelectorAll('[name=copy-source]').forEach(e=>e.checked=action==='copy-all');return}
 if(action==='new-local'){localForm();return}
 if(action.startsWith('edit-local:')){localForm(data.local_records.find(r=>r.id===action.slice(11)));return}
 if(action==='save-local'){
  if(!value('record-key')?.trim())throw fieldError('请填写匹配键','record-key');if(!value('record-source')?.trim())throw fieldError('请填写资料来源或依据','record-source');
  const kind=value('record-kind'),r={kind,key:value('local-id')?document.getElementById('record-key').dataset.originalKey:value('record-key'),source:value('record-source'),aliases:value('record-aliases').split(/[,，\n]+/).filter(Boolean),tags:value('record-tags'),category:value('record-category')};
  if(value('local-id'))Object.assign(r,{id:value('local-id'),version:Number(value('local-version'))});
  if(kind==='text')Object.assign(r,{language:value('record-language'),generic:document.getElementById('record-generic').checked,requires:value('record-requires'),body:Object.fromEntries(copyFields.map(([k])=>[k,value('record-body-'+k)]))});
  else if(kind==='music_rule')Object.assign(r,{match_tags:value('record-match'),music_tags:value('record-music')});
  else Object.assign(r,{property:value('record-property')||kind,th:value('record-th'),en:value('record-en'),confirmed:document.getElementById('record-confirmed').checked});
  await api('local-save',r);closeModal();await loadState();toast('资料已保存');return;
 }
 if(action.startsWith('delete-local:')){const r=data.local_records.find(r=>r.id===action.slice(13));modal('删除本地资料',`<p>删除“${esc(recordLabel(r))}”。历史任务已保存的资料快照仍然保留。</p>`,btn('取消','close')+btn('确认删除','confirm-local:'+r.id,'danger'));return}
 if(action.startsWith('confirm-local:')){const r=data.local_records.find(r=>r.id===action.slice(14));await api('local-delete',{id:r.id,version:r.version});closeModal();await loadState();return}
 if(action==='import-local'){const r=await api('local-import',{});if(r.cancelled){toast('已取消选择');return}await loadState();modal('资料导入结果',`<p>成功 ${r.imported.length} 条，失败 ${r.errors.length} 条。</p>${r.errors.map(e=>`<p>第${e.row}行：${esc(e.error)}</p>`).join('')}<p>具体商品规格和标签未匹配结果在任务预览中查看。</p>`);return}
 if(action==='export-local'){const url=URL.createObjectURL(new Blob([JSON.stringify(data.local_records,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='TikTokVideoMaker_local_records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}
 return await localActions(action);
}catch(e){reportError(e)}};
document.addEventListener('change',e=>{if(e.target.id==='local-kind'){localKind=e.target.value;render()}if(e.target.id==='local-language')refreshLocalPool();if(e.target.id==='local-mode')updateBatchCount()});

document.addEventListener('change',e=>{if(e.target.matches('[data-default-language]'))settings.production={...settings.production,local_copy:{...settings.production?.local_copy,language:e.target.value}};if(e.target.matches('[data-default-resolution]'))settings.production={...settings.production,resolution:e.target.value,fit:'contain'}});
